CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text, preferences jsonb NOT NULL DEFAULT '{}');
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name','')); RETURN NEW; END $$;
CREATE TRIGGER ortakyuva_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.families (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), child_name text NOT NULL, created_by uuid NOT NULL, invite_code uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.families TO authenticated; GRANT ALL ON public.families TO service_role;
ALTER TABLE public.families ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), family_id uuid NOT NULL REFERENCES public.families(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, parent_role text NOT NULL CHECK(parent_role IN ('anne','baba')), access text NOT NULL DEFAULT 'viewer' CHECK(access IN ('editor','viewer')), display_name text NOT NULL DEFAULT '', UNIQUE(family_id,user_id));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.family_access(fid uuid, edit_required boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE family_id=fid AND user_id=auth.uid() AND (NOT edit_required OR access='editor')) $$;
REVOKE ALL ON FUNCTION public.family_access(uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.family_access(uuid,boolean) TO authenticated;
CREATE POLICY members_read ON public.families FOR SELECT TO authenticated USING(public.family_access(id));
CREATE POLICY members_roles_read ON public.user_roles FOR SELECT TO authenticated USING(public.family_access(family_id));
CREATE TABLE public.family_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), family_id uuid NOT NULL REFERENCES public.families(id) ON DELETE CASCADE, author_id uuid NOT NULL DEFAULT auth.uid(), kind text NOT NULL CHECK(kind IN ('event','task','health','message','note','status','screen')), payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.family_records TO authenticated; GRANT ALL ON public.family_records TO service_role;
ALTER TABLE public.family_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY record_read ON public.family_records FOR SELECT TO authenticated USING(public.family_access(family_id));
CREATE POLICY record_insert ON public.family_records FOR INSERT TO authenticated WITH CHECK(author_id=auth.uid() AND public.family_access(family_id,kind NOT IN ('message','status')));
CREATE POLICY record_update ON public.family_records FOR UPDATE TO authenticated USING(public.family_access(family_id,true)) WITH CHECK(public.family_access(family_id,true));
CREATE POLICY record_delete ON public.family_records FOR DELETE TO authenticated USING(public.family_access(family_id,true));
CREATE INDEX records_family ON public.family_records(family_id,created_at);
CREATE FUNCTION public.create_family(child text, parent text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE fid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF length(trim(child))<1 OR length(child)>100 THEN RAISE EXCEPTION 'Invalid child name'; END IF; INSERT INTO public.families(child_name,created_by) VALUES(trim(child),auth.uid()) RETURNING id INTO fid; INSERT INTO public.user_roles(family_id,user_id,parent_role,access,display_name) SELECT fid,auth.uid(),parent,'editor',display_name FROM public.profiles WHERE id=auth.uid(); RETURN fid; END $$;
CREATE FUNCTION public.join_family(code uuid,parent text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE fid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT id INTO fid FROM public.families WHERE invite_code=code; IF fid IS NULL THEN RAISE EXCEPTION 'Invalid invitation'; END IF; IF (SELECT count(*) FROM public.user_roles WHERE family_id=fid)>=2 THEN RAISE EXCEPTION 'Family already has two parents'; END IF; INSERT INTO public.user_roles(family_id,user_id,parent_role,access,display_name) SELECT fid,auth.uid(),parent,'viewer',display_name FROM public.profiles WHERE id=auth.uid(); RETURN fid; END $$;
CREATE FUNCTION public.set_family_access(fid uuid,member uuid,permission text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.families WHERE id=fid AND created_by=auth.uid()) THEN RAISE EXCEPTION 'Owner only'; END IF; IF member=auth.uid() THEN RAISE EXCEPTION 'Cannot change owner'; END IF; UPDATE public.user_roles SET access=permission WHERE family_id=fid AND user_id=member; END $$;
REVOKE ALL ON FUNCTION public.create_family(text,text),public.join_family(uuid,text),public.set_family_access(uuid,uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_family(text,text),public.join_family(uuid,text),public.set_family_access(uuid,uuid,text) TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.family_records;